// A measured frame where the dataset has one (the first 101, 10 s). Past that the series is continued with the
// same forward model: the clean signal plus Gaussian noise of variance a*y + b, the noise model fitted to the
// measured frames. The draw is a fixed hash of (frame, wavenumber), so every render shows the same series.
const unit = n => { let x = (n ^ 0x9e3779b9) >>> 0; x = Math.imul(x ^ (x >>> 16), 0x85ebca6b); x = Math.imul(x ^ (x >>> 13), 0xc2b2ae35); return ((x ^ (x >>> 16)) >>> 0) / 4294967296 }
const gauss = n => Math.sqrt(-2 * Math.log(unit(2 * n) || 1e-12)) * Math.cos(2 * Math.PI * unit(2 * n + 1))
export const measuredFrames = P.noisy.length
export const noisyAt = (j, i) => {
  if (j < P.noisy.length) return P.noisy[j][i] / P.scale
  const y = P.raman[i] + P.F0.reduce((a, f, k) => a + f[i] * Math.exp(-P.lam[k] * j * P.dt), 0)
  return y + Math.sqrt(P.noise[0] * y + P.noise[1]) * gauss(j * P.raman.length + i)
}
// frame start times for a series of n frames
export const frameTimes = n => Array.from({ length: n }, (_, j) => j * P.dt)
export const fluorAt = (k, i, t) => P.F0[k][i] * Math.exp(-P.lam[k] * t)
export const cleanAt = (i, t) => P.raman[i] + fluorAt(0, i, t) + fluorAt(1, i, t) + fluorAt(2, i, t)
// the same sample in the { R, F, lam } form the surface component takes
export const series = { R: P.raman, F: P.F0, lam: P.lam }
